package org.xingmu.tv;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.provider.Settings;import android.widget.*;import java.util.concurrent.*;
public final class SettingsActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private TextView status;private String importSection="domestic",importCountry="未分类";
 @Override public void onCreate(Bundle b){super.onCreate(b);if(b!=null){importSection=b.getString("importSection","domestic");importCountry=b.getString("importCountry","未分类");}LinearLayout content=TvUi.root(this);ScrollView scroll=new ScrollView(this);LinearLayout root=TvUi.col(this);scroll.addView(root);content.addView(scroll);root.addView(TvUi.text(this,"设置与内容来源",28,TvUi.INK));TvUi.gap(this,root,16);
 Switch boot=new Switch(this);boot.setText("开机进入星幕 TV");boot.setTextColor(TvUi.INK);boot.setTextSize(19);boot.setChecked(getSharedPreferences("settings",0).getBoolean("boot",false));boot.setOnCheckedChangeListener((v,checked)->{getSharedPreferences("settings",0).edit().putBoolean("boot",checked).apply();if(checked&&Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},6);});root.addView(boot);root.addView(TvUi.text(this,"Android 10+ 通常限制后台直接打开界面。请在小米电视设置中允许自启动；不支持时提供开机提醒。默认桌面是另一种可选方式，不会强制更改。首次安装后须先打开一次应用。",15,TvUi.MUTED));TvUi.gap(this,root,16);
 add(root,"打开系统应用设置",()->launch(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+getPackageName()))));
 add(root,"可选：设为默认电视桌面",()->new AlertDialog.Builder(this).setTitle("启用桌面入口").setMessage("将让星幕 TV 出现在系统默认桌面候选中。你仍需在系统设置中自行选择；部分小米系统不允许更换。手机也可打开此项目，但不建议替代完整手机桌面。取消此选项不会更改当前桌面。").setNegativeButton("取消",null).setPositiveButton("打开选择",(d,w)->{getPackageManager().setComponentEnabledSetting(new ComponentName(this,"org.xingmu.tv.TvHome"),PackageManager.COMPONENT_ENABLED_STATE_ENABLED,PackageManager.DONT_KILL_APP);launch(new Intent(Settings.ACTION_HOME_SETTINGS));}).show());
 add(root,"关闭桌面候选入口",()->{getPackageManager().setComponentEnabledSetting(new ComponentName(this,"org.xingmu.tv.TvHome"),PackageManager.COMPONENT_ENABLED_STATE_DISABLED,PackageManager.DONT_KILL_APP);TvUi.toast(this,"桌面入口已关闭，请确认系统原桌面已恢复");});
 TvUi.gap(this,root,14);root.addView(TvUi.text(this,"免费与授权来源",22,TvUi.INK));root.addView(TvUi.text(this,"内置 myIPTV 直播目录、Lightconer 标准影视接口与开放电影。支持导入自己的播放列表和 TVBox 标准数据源。官网可能需要账号，播放支持情况由站点决定。",15,TvUi.MUTED));
 add(root,"刷新 myIPTV 电视直播源",()->{status.setText("正在刷新 myIPTV…");worker.execute(()->{String result;try{result=new MyIptvRepository(this).update();}catch(Exception e){result="刷新失败，已有目录保留："+e.getMessage();}String text=result;runOnUiThread(()->{if(!isDestroyed())status.setText(text);});});});
 add(root,"刷新 zbds 电视源（M3U / TXT）",()->{status.setText("正在下载 zbds 直播列表…");worker.execute(()->{String message;try{message=new ZbdsRepository(this).update();}catch(Exception e){message="更新失败，已有目录保留："+e.getMessage();}String result=message;runOnUiThread(()->{if(!isDestroyed())status.setText(result);});});});
 add(root,"导入我的播放列表（JSON / M3U / TXT / XSPF）",()->chooseImport(()->{Intent open=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*");try{startActivityForResult(open,10);}catch(ActivityNotFoundException e){TvUi.toast(this,"系统没有文件选择器，可使用粘贴或 HTTPS 导入");}}));
 add(root,"从 HTTPS 地址导入播放列表",()->chooseImport(()->{EditText url=new EditText(this);url.setSingleLine(true);url.setHint("https://…/playlist.m3u");new AlertDialog.Builder(this).setTitle("导入远程播放列表").setView(url).setNegativeButton("取消",null).setPositiveButton("导入",(d,w)->{String section=importSection,country=importCountry;importTask(()->new CatalogRepository(this).fetch(url.getText().toString().trim(),section,country));}).show();}));
 add(root,"粘贴播放地址或列表文本",()->chooseImport(()->{EditText text=new EditText(this);text.setMinLines(3);text.setHint("https://…/video.mp4\n或 M3U / TXT / JSON / XSPF 文本");new AlertDialog.Builder(this).setTitle("粘贴我的媒体").setView(text).setNegativeButton("取消",null).setPositiveButton("导入",(d,w)->{String value=text.getText().toString(),section=importSection,country=importCountry;importTask(()->new CatalogRepository(this).merge(value,section,country));}).show();}));
 add(root,"导入 TVBox 配置文件",()->{Intent open=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*");try{startActivityForResult(open,10);}catch(ActivityNotFoundException e){TvUi.toast(this,"系统没有文件选择器，可使用 HTTPS 地址导入");}});
 add(root,"添加影视源（接口 / TVBox 订阅，支持多行）",()->{EditText text=new EditText(this);text.setMinLines(3);text.setHint("每行一个公开 HTTP/HTTPS 影视接口或 TVBox 配置地址");new AlertDialog.Builder(this).setTitle("添加影视来源").setView(text).setNegativeButton("取消",null).setPositiveButton("导入",(d,w)->{String addresses=text.getText().toString();status.setText("正在识别并导入来源…");worker.execute(()->{String message;try{message=new SourceRepository(this).addRemote(addresses);}catch(Exception e){message="导入失败："+e.getMessage();}String result=message;runOnUiThread(()->{if(!isDestroyed())status.setText(result);});});}).show();});
 add(root,"TVBox 导入报告与直播更新",()->startActivity(new Intent(this,SourceActivity.class)));
 add(root,"清除自定义目录",()->new AlertDialog.Builder(this).setTitle("清除自定义目录？").setMessage("内置官方入口与开放电影会保留。").setNegativeButton("取消",null).setPositiveButton("清除",(d,w)->{new CatalogRepository(this).clear();status.setText("自定义目录已清除");}).show());
 TvUi.gap(this,root,14);root.addView(TvUi.text(this,"播放与记录",22,TvUi.INK));Switch autoplay=new Switch(this);autoplay.setText("点播结束后播放下一项");autoplay.setTextColor(TvUi.INK);autoplay.setChecked(getSharedPreferences("settings",0).getBoolean("autoplay",false));autoplay.setOnCheckedChangeListener((v,value)->getSharedPreferences("settings",0).edit().putBoolean("autoplay",value).apply());root.addView(autoplay);add(root,"清除观看历史与续播位置",()->new AlertDialog.Builder(this).setTitle("清除观看记录？").setMessage("收藏会保留。").setNegativeButton("取消",null).setPositiveButton("清除",(d,w)->{new WatchStore(this).clearHistory();TvUi.toast(this,"观看记录已清除");}).show());
 status=TvUi.text(this,"内置播放器支持 HTTP/HTTPS MP4、HLS、DASH；无需安装 VPN。",15,TvUi.ACCENT);root.addView(status);add(root,"返回首页",()->finish());
 }
 private void chooseImport(Runnable action){String[] keys={"domestic","foreign","films"};new AlertDialog.Builder(this).setTitle("播放列表放在哪个栏目？").setItems(new String[]{"国内电视直播","国外电视直播","网络影视"},(d,n)->{importSection=keys[n];EditText country=new EditText(this);country.setSingleLine(true);country.setHint(n==1?"国家，例如：日本":"可留空");new AlertDialog.Builder(this).setTitle("国家与导入说明").setMessage("仅导入你有权访问的媒体。播放支持公开 HTTP/HTTPS 地址；分类从列表分组读取。纯戏曲直播需要 JSON operaOnly 声明。已有目录会保留。JSON 使用自身栏目字段。").setView(country).setNegativeButton("取消",null).setPositiveButton("继续",(dialog,w)->{importCountry=country.getText().toString().trim();if(importCountry.isEmpty())importCountry="未分类";action.run();}).show();}).show();}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("importSection",importSection);out.putString("importCountry",importCountry);}
 private void add(LinearLayout root,String text,Runnable action){Button b=TvUi.button(this,text);b.setOnClickListener(v->action.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=TvUi.dp(this,10);root.addView(b,p);}
 private void launch(Intent intent){try{startActivity(intent);}catch(ActivityNotFoundException|SecurityException e){TvUi.toast(this,"系统不提供此入口，请从电视设置手动操作");}}
 private interface Import {int run()throws Exception;}
 private void importTask(Import task){status.setText("正在导入…");worker.execute(()->{String message;try{int count=task.run();message="已导入 "+count+" 项。"+new SourceRepository(this).report();}catch(Exception e){message="导入失败："+e.getMessage();}String result=message;runOnUiThread(()->{if(!isDestroyed())status.setText(result);});});}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==10&&result==RESULT_OK&&data!=null&&data.getData()!=null)importTask(()->new CatalogRepository(this).merge(CatalogRepository.read(getContentResolver().openInputStream(data.getData())),importSection,importCountry));}
 @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
